<span class="line">        <span class="token class-name">IList<span class="token punctuation">&lt;</span>DateTimeOffset<span class="token punctuation">&gt;</span></span> state <span class="token operator">=</span> <span class="token punctuation">(</span>IList<span class="token operator">&lt;</span>DateTimeOffset<span class="token operator">&gt;</span><span class="token punctuation">)</span> dataMap<span class="token punctuation">[</span><span class="token string">&quot;myStateData&quot;</span><span class="token punctuation">]</span><span class="token operator">!</span><span class="token punctuation">;</span></span>
